function toggleMP(idx) {
  var expand = document.getElementById('mpexpand-'+idx);
  var row = document.getElementById('mprow-'+idx);
  var isOpen = expand.style.display !== 'none';
  document.querySelectorAll('[id^="mpexpand-"]').forEach(function(el){ el.style.display='none'; });
  document.querySelectorAll('.mp-row').forEach(function(el){ el.style.background=''; });
  if (!isOpen) {
    expand.style.display = '';
    row.style.background = 'rgba(241,138,0,0.04)';
    setTimeout(function(){ expand.scrollIntoView({behavior:'smooth',block:'nearest'}); }, 50);
    var mp = RAW.mp_list[idx];
    var MM = MESES;
    var opts = {responsive:true,maintainAspectRatio:false,layout:{padding:{top:14}},
      plugins:{legend:{display:false},datalabels:{display:false},tooltip:{callbacks:{label:function(c){return c.raw;}}}},
      scales:{x:{grid:{display:false},ticks:{color:'#9ca3af',font:{size:9}}},y:{grid:{color:'rgba(0,0,0,0.04)'},ticks:{color:'#9ca3af',font:{size:9}}}}};
    var mesC=MM.filter(function(m){return mp.costos[m]!=null;});
    mkChart('mp-chart-costo-'+idx,'line',{labels:mesC,datasets:[{data:mesC.map(function(m){return mp.costos[m];}),borderColor:'#f18a00',backgroundColor:'rgba(241,138,0,0.1)',tension:.3,pointRadius:3,fill:true,borderWidth:2}]},opts);
    var mesLT=MM.filter(function(m){return typeof mp.lead_time[m]==='number';});
    if(mesLT.length){mkChart('mp-chart-lt-'+idx,'bar',{labels:mesLT,datasets:[{data:mesLT.map(function(m){return mp.lead_time[m];}),backgroundColor:'rgba(34,32,28,0.15)',borderColor:'rgba(34,32,28,0.4)',borderWidth:1.5,borderRadius:4}]},opts);}
    var mesCP=MM.filter(function(m){return typeof mp.cond_pago[m]==='number';});
    if(mesCP.length){mkChart('mp-chart-cp-'+idx,'bar',{labels:mesCP,datasets:[{data:mesCP.map(function(m){return mp.cond_pago[m];}),backgroundColor:'rgba(241,138,0,0.3)',borderColor:'rgba(241,138,0,0.7)',borderWidth:1.5,borderRadius:4}]},opts);}
  }
}
function renderSparklines() {
  if(!RAW.mp_list) return;
  var MM = MESES;
  RAW.mp_list.forEach(function(mp,i){
    var cv=document.getElementById('spark-'+i); if(!cv) return;
    var vals=MM.map(function(m){return mp.costos[m]||null;}).filter(Boolean); if(!vals.length) return;
    mkChart('spark-'+i,'line',{labels:vals.map(function(_,j){return j;}),datasets:[{data:vals,borderColor:'#f18a00',borderWidth:1.5,pointRadius:0,tension:.3,fill:false}]},{responsive:false,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:false},datalabels:{display:false}},scales:{x:{display:false},y:{display:false}}});
  });
}
function renderMP() {
  if(!RAW.mp_list) return;
  var MM = MESES;
  var tbody = document.getElementById('mp-tbody');
  if(!tbody) return;
  function avg(obj){var vals=Object.values(obj||{}).filter(function(v){return typeof v==='number';});return vals.length?vals.reduce(function(a,b){return a+b;},0)/vals.length:null;}
  function fmtMoneda(sym, val){
    if(val==null) return '—';
    return sym==='$' ? '$ '+val.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2})
                          : sym+' '+val.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2});
  }
  function fmtPctVar(v){if(v==null||v===0)return{txt:'0.0%',color:'#9ca3af'};var c=v>0?'#dc2626':'#16a34a';return{txt:(v>0?'+':'')+(v*100).toFixed(1)+'%',color:c};}
  tbody.innerHTML = RAW.mp_list.map(function(mp, idx){
    var lastMes=mp.mes_last_label, prevMes=mp.mes_ant_label;
    var ultimoCosto=mp.costos[lastMes];
    var varEneJul=fmtPctVar(mp.var_ene_jul); var varMesAnt=fmtPctVar(mp.var_mes_ant);
    var leadTimeProm=avg(mp.lead_time); var condPagoProm=avg(mp.cond_pago);
    var selMP=selMeses();
    var cantUtilizada=sumMesObj(mp.cant_utilizada, selMP);
    var cantRecibida=sumMesObj(mp.cant_recibida, selMP);
    var precioTotalArs=sumMesObj(mp.precio_total_ars, selMP);
    var row='<tr class="mp-row" id="mprow-'+idx+'" onclick="toggleMP('+idx+')" style="cursor:pointer;border-bottom:1px solid #e5e7eb;transition:background .15s">'
      +'<td style="padding:12px 8px;font-size:13px;color:#9ca3af;width:32px">'+(idx+1)+'</td>'
      +'<td style="padding:12px 8px"><div style="font-size:13px;font-weight:700;color:#111827">'+mp.nombre.replace(/^\[\d+\]\s*/,'')+'</div><div style="font-size:11px;color:#9ca3af;margin-top:2px">'+mp.proveedor+'</div></td>'
      +'<td style="padding:12px 8px;font-size:12px;color:#4b5563">'+mp.moneda+'</td>'
      +'<td style="padding:12px 8px;font-size:13px;font-weight:600;color:#111827">'+fmtMoneda(mp.moneda,ultimoCosto)+'</td>'
      +'<td style="padding:12px 8px;font-size:13px;font-weight:600;color:'+varEneJul.color+';text-align:right">'+varEneJul.txt+'</td>'
      +'<td style="padding:12px 8px;text-align:right"><span style="font-size:13px;font-weight:600;color:'+varMesAnt.color+'">'+varMesAnt.txt+'</span><div style="font-size:9px;color:#9ca3af;margin-top:1px">'+prevMes+'→'+lastMes+'</div></td>'
      +'<td style="padding:12px 8px;font-size:13px;color:#374151;text-align:center">'+(leadTimeProm!=null?leadTimeProm.toFixed(1)+' d':'—')+'</td>'
      +'<td style="padding:12px 8px;font-size:13px;color:#374151;text-align:center">'+(condPagoProm!=null?condPagoProm.toFixed(1)+' d':'—')+'</td>'
      +'<td style="padding:12px 8px;font-size:13px;color:#374151;text-align:center">'+(cantUtilizada!=null?fmtN(cantUtilizada)+' Kg':'—')+'</td>'
      +'<td style="padding:12px 8px;font-size:13px;color:#374151;text-align:center">'+(cantRecibida!=null?fmtN(cantRecibida)+' Kg':'—')+'</td>'
      +'<td style="padding:12px 8px;font-size:13px;color:#374151;text-align:right">'+(precioTotalArs!=null?'$ '+fmtN(precioTotalArs):'—')+'</td>'
      +'</tr>';
    var expand='<tr id="mpexpand-'+idx+'" style="display:none"><td colspan="11" style="padding:0;background:#f9fafb"><div style="padding:16px">'
      +'<div style="font-size:11px;font-weight:700;color:#6b7280;margin-bottom:12px;text-transform:uppercase;letter-spacing:.5px">'+mp.nombre.replace(/^\[\d+\]\s*/,'')+' · '+mp.proveedor+' · '+mp.moneda+'</div>'
      +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:16px">'
      +'<div><div style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">Evolución Costo</div><div style="height:150px;position:relative"><canvas id="mp-chart-costo-'+idx+'"></canvas></div></div>'
      +'<div><div style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">Lead Time (días)</div><div style="height:150px;position:relative"><canvas id="mp-chart-lt-'+idx+'"></canvas></div></div>'
      +'<div><div style="font-size:10px;font-weight:700;color:#9ca3af;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">Cond. Pago (días)</div><div style="height:150px;position:relative"><canvas id="mp-chart-cp-'+idx+'"></canvas></div></div>'
      +'</div></div></td></tr>';
    return row+expand;
  }).join('');
}

document.addEventListener('DOMContentLoaded',init);